with flattened as (select id, customer_id, coupon_codes, li_item.promo from carts lateral view explode(items) e as li_item) select promo, count(case when promo = 'VIP' then 1 end) as vip_count, count(*) filter (where promo = 'WELCOME5') as welcome5_rows, sort_array(collect_set(promo)) as promo_list, sort_array(collect_set(promo)) as promo_list_2, count_if(promo = 'WELCOME5') as welcome5_events from flattened group by promo order by vip_count nulls first;
